#pragma once

#include "CoreMinimal.h"
#include "Level/ChunkLayouts.h"

/**
 * The authored 12-chunk / 24-variant catalogue as placeholder geometry: true constants of the level design, one row
 * per piece. X is a fraction of the chunk length (0 entrance, 1 exit), Z a fraction of the arena height (0 bottom).
 * Solid and Wind rows are rects [X0,X1] x [Z0,Z1]; Trap and Enemy rows are a point (X0, Z0); an Enemy row with
 * bFeetOnLand gives the land top it stands on in Z0. The GDD gives words, not coordinates: these are the level
 * designer's authored numbers, and playtests tune them. ChunkLayouts::Validate / ValidateBypass check every row.
 */
struct FChunkPieceRow
{
	int32 Chunk;
	TCHAR Variant;
	EChunkPieceKind Kind;
	EWindRole Role;
	EChunkMechanic Mechanic;
	bool bBypass;
	EChunkShotColour Colour;
	bool bFeetOnLand;
	float X0;
	float X1;
	float Z0;
	float Z1;
};

